let ai = null;
try {
  const raw = $json.output[0].content[0].text;
  ai = (typeof raw === 'string') ? JSON.parse(raw) : raw;
} catch (e) { ai = null; }

const em = $("On Incoming Email").item.json;
const fromText = (em.from && em.from.text) ? em.from.text : '';
const fromAddr = (em.from && em.from.value && em.from.value[0]) ? em.from.value[0].address : '';
const subject = em.subject || '';
const threadId = em.threadId || '';

if (!ai) {
  return { json: { category: "NOT_RECRUITER", is_recruiter: false, confidence: 0, reasoning: "parse_failed", draft_reply: "", from_text: fromText, from_addr: fromAddr, subject: subject, thread_id: threadId } };
}

const category = ai.category || "NOT_RECRUITER";
const is_recruiter = category !== "NOT_RECRUITER";
const confidence = Number(ai.confidence) || 0;

return { json: {
  category: category,
  is_recruiter: is_recruiter,
  confidence: confidence,
  low_confidence: confidence < 0.5,
  reasoning: ai.reasoning || '',
  draft_reply: ai.draft_reply || '',
  from_text: fromText,
  from_addr: fromAddr,
  subject: subject,
  thread_id: threadId,
} };
